window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφρύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1652 na letra ε · nº geral 12891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φρύγω.</p></section></article>\n<article id=\"entry-dgp-12892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1653 na letra ε · nº geral 12892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não controla os sentimentos; que está fora de si; insensato 2 exaltado; entusiasta. 〈ἐκ, φρήν〉</p></section></article>\n<article id=\"entry-dgp-12893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυγγάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1654 na letra ε · nº geral 12893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 = ἐκφεύγω 2 recuperar-se de doença.</p></section></article>\n<article id=\"entry-dgp-12894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφυγε</h1><div class=\"entry-meta\"><span>DGP · ordem 1655 na letra ε · nº geral 12894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 poét. de ἐκφεύγω.</p></section></article>\n<article id=\"entry-dgp-12895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυγέειν</h1><div class=\"entry-meta\"><span>DGP · ordem 1656 na letra ε · nº geral 12895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 ép. de ἐκφεύγω.</p></section></article>\n<article id=\"entry-dgp-12896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυλάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1657 na letra ε · nº geral 12896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vigiar com cuidado; velar atentamente.</p></section></article>\n<article id=\"entry-dgp-12897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυλλοφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1658 na letra ε · nº geral 12897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excluir de uma lista (escrevendo o sufrágio em folha de oliveira). 〈ἐκ, φύλλον, φορέω〉</p></section></article>\n<article id=\"entry-dgp-12898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκφυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1659 na letra ε · nº geral 12898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estrangeiro 2 estranho; extraordinário; inesperado. 〈ἐκ, φυλή〉</p></section></article>\n<article id=\"entry-dgp-12899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφῦναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1660 na letra ε · nº geral 12899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ἐκφύω.</p></section></article>\n<article id=\"entry-dgp-12900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυσάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1661 na letra ε · nº geral 12900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 soprar 2 exalar (fogo, ardor); ἐκφ. βαρὺν ὕπνον teócr. roncar forte 3 soprar sobre; atiçar 4 bíbl. dispersar com sopro 5 irromper 6 bufar ♦ pas. 7 dispersar-se; esvair-se 8 part. perf. ἐκπεφυσημένος inflado; orgulhoso (pessoa).</p></section></article>\n<article id=\"entry-dgp-12901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφυσιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1662 na letra ε · nº geral 12901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar com um sopro; exalar. 〈ἐκφυσάω〉</p></section></article>\n<article id=\"entry-dgp-12902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1663 na letra ε · nº geral 12902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (pai, mãe) fazer nascer; dar nascimento a; engendrar 2 (semente, terra) produzir ♦ intr. (aor.2 ἐξέφυν, perf.1 ἐκπέφυκα, ép. ἐκπέφυα) e méd. 3 nascer de; provir de, gen. 4 (grão) germinar ♦ méd.-pas. 5 nascer: λάλημα ἐχπεφυκός sóf. um tagarela de nascença 6 derivar de, gen.</p></section></article>\n<article id=\"entry-dgp-12903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφωνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1664 na letra ε · nº geral 12903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falar bem forte; gritar 2 pronunciar em voz alta, ac. ♦ pas. 3 ser pronunciado.</p></section></article>\n<article id=\"entry-dgp-12904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκφώνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1665 na letra ε · nº geral 12904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exclamação 2 pronúncia. 〈ἐκφωνέω〉</p></section></article>\n<article id=\"entry-dgp-12905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχαλινόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1666 na letra ε · nº geral 12905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tirar o freio (do cavalo).</p></section></article>\n<article id=\"entry-dgp-12906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχαράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1667 na letra ε · nº geral 12906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω raspar; apagar.</p></section></article>\n<article id=\"entry-dgp-12907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκχεον</h1><div class=\"entry-meta\"><span>DGP · ordem 1668 na letra ε · nº geral 12907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. ép. de ἐκχέω.</p></section></article>\n<article id=\"entry-dgp-12908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχεύατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1669 na letra ε · nº geral 12908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐκχέω.</p></section></article>\n<article id=\"entry-dgp-12909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1670 na letra ε · nº geral 12909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκχεύσω, aor. ἐξέχεα; pas. aor.1 ἐξεχύθην, perf. ἐκκέχυμαι) 1 verter (vinho) 2 derramar (sangue, lágrimas) 3 divulgar; difundir (canto, palavra) 4 deixar correr como água; deixar perder; dissipar; esbanjar 5 fazer escorrer; fazer correr 6 fazer derramar (lágrimas) 7 estender; desdobrar (velas) ♦ méd. 8 verter para si ♦ pas. 9 espalhar-se; (líquido) transbordar 10 (coisas) espalhar-se em grande quantidade 11 (multidão) espalhar-se; dispersar-se 12 entregar-se inteiramente a algo ou a alguém, dat. ou εἰς e ac. 13 esparramar-se de prazer; regozijar-se 14 (pessoa) estirar-se languidamente.</p></section></article>\n<article id=\"entry-dgp-12910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχράω1</h1><div class=\"entry-meta\"><span>DGP · ordem 1671 na letra ε · nº geral 12910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só fut. ἐκχρήσει e aor. ἐξέχρησε) 1 ser suficiente; bastar a alguém, dat.: οὐκ ἐξέχρησέ σφι ἡ ἡμέρα ναυμαχίην ποιήσασθαι her. não lhe bastou o dia para fazer a batalha naval 2 impes. bastar a; ser suportável, dat. e or. inf.: κῶς ταῦτα βασιλέϊ ἐκχρήσει περιυβρίσθαι; her. como o rei suportará sofrer tais ultrajes?</p></section></article>\n<article id=\"entry-dgp-12911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχράω2</h1><div class=\"entry-meta\"><span>DGP · ordem 1672 na letra ε · nº geral 12911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. ἐξέχρη) predizer.</p></section></article>\n<article id=\"entry-dgp-12912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχρηματίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1673 na letra ε · nº geral 12912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tirar dinheiro de alguém, ac.; extorquir.</p></section></article>\n<article id=\"entry-dgp-12913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχύμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1674 na letra ε · nº geral 12913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 méd. ép. de ἐκχέω.</p></section></article>\n<article id=\"entry-dgp-12914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1675 na letra ε · nº geral 12914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = ἐκχέω.</p></section></article>\n<article id=\"entry-dgp-12915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχύτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1676 na letra ε · nº geral 12915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pródigo. 〈ἐκχέω〉</p></section></article>\n<article id=\"entry-dgp-12916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκχυτο</h1><div class=\"entry-meta\"><span>DGP · ordem 1677 na letra ε · nº geral 12916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. méd. ép. de ἐκχέω.</p></section></article>\n<article id=\"entry-dgp-12917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχώννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1678 na letra ε · nº geral 12917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐκχώσω) 1 amontoar (terra) ♦ pas. 2 terraplenar (cidade) 3 ser construído em terras de aluvião 4 encher-se com terra de aluvião.</p></section></article>\n<article id=\"entry-dgp-12918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1679 na letra ε · nº geral 12918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sair; ir embora; partir de, gen. ou ἐκ e gen.: ἐκχ. τοῦ ζῆν pol. deixar a vida, i.e., morrer 2 retirar-se em favor de alguém; ceder o lugar para alguém, dat. 3 ceder a alguém, dat., em algo, gen. ou ac.</p></section></article>\n<article id=\"entry-dgp-12919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκχώρησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1680 na letra ε · nº geral 12919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saída; partida. 〈ἐκχωρέω〉</p></section></article>\n<article id=\"entry-dgp-12920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκψύχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1681 na letra ε · nº geral 12920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. desfalecer; desmaiar 2 respirar com dificuldade 3 dar o último suspiro; morrer.</p></section></article>\n<article id=\"entry-dgp-12921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκών, οῦσα, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1682 na letra ε · nº geral 12921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ἑκόντος, ἑκούσης, ἑκόντος 1 que age voluntariamente, espontaneamente, de bom grado: ἑκόνθ᾽ ἑκόντι Ζηνὶ συμπαραστατεῖν ésql. acolher de bom grado a Zeus, que de bom grado me acolhe; ἑκὼν εἶναι por pleno consentimento; por decisão pessoal, εἴ τις ἑκὼν εἶναι ἐπὶ τὸ τοιοῦτον ἀφικνεῖται plat. se uma pessoa chega a tal ponto por decisão própria 2 que consente; concorde; οὐχ ἑκών a contragosto, malgrado: ἐμοῦ μὲν οὐχ ἑκόντος sóf. contra minha vontade, ἠνάγκακεν ἡμᾶς οὐκ ἑκόντας ὁμολογεῖν plat. forçou-nos a concordar, contra nossa vontade.</p></section></article>\n<article id=\"entry-dgp-12922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλᾷ</h1><div class=\"entry-meta\"><span>DGP · ordem 1683 na letra ε · nº geral 12922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. ou fut. ind. de ἐλάω1.</p></section></article>\n<article id=\"entry-dgp-12923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάα, άας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1684 na letra ε · nº geral 12923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἐλαία.</p></section></article>\n<article id=\"entry-dgp-12924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάαν</h1><div class=\"entry-meta\"><span>DGP · ordem 1685 na letra ε · nº geral 12924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ou fut. ép. de ἐλάω1.</p></section></article>\n<article id=\"entry-dgp-12925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλαβον</h1><div class=\"entry-meta\"><span>DGP · ordem 1686 na letra ε · nº geral 12925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λαμβάνω.</p></section></article>\n<article id=\"entry-dgp-12926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαθείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1687 na letra ε · nº geral 12926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλαθον</h1><div class=\"entry-meta\"><span>DGP · ordem 1688 na letra ε · nº geral 12927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de λανθάνω.</p></section></article>\n<article id=\"entry-dgp-12928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1689 na letra ε · nº geral 12928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oliveira 2 oliva.</p></section></article>\n<article id=\"entry-dgp-12929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαιάεις</h1><div class=\"entry-meta\"><span>DGP · ordem 1690 na letra ε · nº geral 12929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἐλαιήεις.</p></section></article>\n<article id=\"entry-dgp-12930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐλαιᾶτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1691 na letra ε · nº geral 12930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">região do porto de Eléia, no Épiro.</p></section></article>\n<article id=\"entry-dgp-12931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαίη</h1><div class=\"entry-meta\"><span>DGP · ordem 1692 na letra ε · nº geral 12931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐλαία.</p></section></article>\n<article id=\"entry-dgp-12932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαιήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1693 na letra ε · nº geral 12932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da oliveira 2 de oliveiras 3 cheio de azeite 4 oleoso. 〈ἐλαία〉</p></section></article>\n<article id=\"entry-dgp-12933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαΐνεος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 1694 na letra ε · nº geral 12933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn., ον poét. = ἐλάϊνος.</p></section></article>\n<article id=\"entry-dgp-12934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάϊνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1695 na letra ε · nº geral 12934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de madeira de oliveira; de ramos de oliveira 2 de óleo de oliva 3 de oliva. 〈ἐλαία〉</p></section></article>\n<article id=\"entry-dgp-12935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλαιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1696 na letra ε · nº geral 12935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 óleo de oliva 2 óleo em geral. 〈ἐλαία〉</p></section></article>\n<article id=\"entry-dgp-12936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαιοπώλης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1697 na letra ε · nº geral 12936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mercador de azeite. 〈ἔλαιον, πωλέω〉</p></section></article>\n<article id=\"entry-dgp-12937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαιόφυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1698 na letra ε · nº geral 12937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 plantação de oliveiras ♦ τὸ ἐλαιό­φυτον 2 campo de oliveiras. 〈ἐλαία, φυτόν〉</p></section></article>\n<article id=\"entry-dgp-12938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαιών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1699 na letra ε · nº geral 12938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 olival ♦ ὁ Ἐλαιών 2 monte das Oliveiras, perto de Jerusalém. 〈ἐλαία〉</p></section></article>\n<article id=\"entry-dgp-12939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλακον</h1><div class=\"entry-meta\"><span>DGP · ordem 1700 na letra ε · nº geral 12939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de λάσκω.</p></section></article>\n<article id=\"entry-dgp-12940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐλαμῖται, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1701 na letra ε · nº geral 12940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. elamitas, povo do sul da Média.</p></section></article>\n<article id=\"entry-dgp-12941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάμφθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1702 na letra ε · nº geral 12941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. pas. jôn. de λαμβάνω.</p></section></article>\n<article id=\"entry-dgp-12942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕλανδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1703 na letra ε · nº geral 12942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se apodera dos homens. 〈ἑλεῖν, ἀνήρ〉</p></section></article>\n<article id=\"entry-dgp-12943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλασα</h1><div class=\"entry-meta\"><span>DGP · ordem 1704 na letra ε · nº geral 12943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. poét. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλασαίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1705 na letra ε · nº geral 12944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. aor. méd. poét. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάσαμες</h1><div class=\"entry-meta\"><span>DGP · ordem 1706 na letra ε · nº geral 12945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. aor. dór. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάσασκε</h1><div class=\"entry-meta\"><span>DGP · ordem 1707 na letra ε · nº geral 12946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. iter. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλασείω</h1><div class=\"entry-meta\"><span>DGP · ordem 1708 na letra ε · nº geral 12947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) desejar fazer uma expedição. 〈ἐλάω1〉</p></section></article>\n<article id=\"entry-dgp-12948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1709 na letra ε · nº geral 12948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cura doenças ♦ οἱ Ἐλάσιοι 2 os curandeiros, família de Argos que tinha o poder de curar a epilepsia. 〈ἐλάω1〉</p></section></article>\n<article id=\"entry-dgp-12949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1710 na letra ε · nº geral 12949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de impelir para frente; impulso para frente 2 envio ao exílio; desterro 3 ação de montar; equitação 4 cargo de cavalaria 5 marcha; expedição 6 cortejo; procissão. 〈ἐλάω1〉</p></section></article>\n<article id=\"entry-dgp-12950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλασσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1711 na letra ε · nº geral 12950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλασσάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1712 na letra ε · nº geral 12951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. méd. poét. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλασσόω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1713 na letra ε · nº geral 12952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἐλαττόω-ῶ (fut. desus., aor. ἠλάτττωσα, perf. ἠλάττωκα; pas. fut. ἐλαττωθήσομαι, aor. ἠλαττώθην, perf. ἠλάττωμαι) at. e méd. 1 tornar menor; tornar inferior; diminuir; enfraquecer; rebaixar; tornar menor que; tornar inferior a, gen. ♦ pas. 2 tornar-se inferior; tornar-se menor; perder o valor; ser rebaixado; tornar inferior a alguém, gen., em algo, dat.; não estar a altura de; estar por baixo de, gen. 3 sofrer uma derrota em; perder em; ser vencido em, dat.; perder; ser vencido sob a influência de alguém ou por algo, ὑπό e gen. 4 ficar em desvantagem; levar a pior em, dat. 〈ἐλάσσων〉</p></section></article>\n<article id=\"entry-dgp-12953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάσσωμα,</h1><div class=\"entry-meta\"><span>DGP · ordem 1714 na letra ε · nº geral 12953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἐλάττωμα, ατος (τό) 1 redução de valor; perda; prejuízo; desvantagem 2 inferioridade. 〈ἐλασσόω〉</p></section></article>\n<article id=\"entry-dgp-12954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάσσων,</h1><div class=\"entry-meta\"><span>DGP · ordem 1715 na letra ε · nº geral 12954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἐλάττων, ων, ον gen. ονος (comp. de ἐλαχύς e de ὀλίγος) 1 inferior em tamanho; menor: διὰ ἐλάσσονος tuc. à menor distância, ἐπὶ ἔλαττον plat. em menor grau 2 inferior em número; menos numeroso que, gen. ou ἤ: οὐκ ἐλάττους τετρακοσίων xen. não menos de quatrocentos, οὐκ ἐλάττους ὀγδοήκοντα d.s. não menos de oitenta 3 inferior em duração; mais breve 4 inferior em qualidade; inferior em algo, dat., a alguém, gen.: περὶ ἐλάσσονος ποιεῖσθαι her. considerar de menor importância, παρ᾽ ἔλαττον τοῦ δέοντος ἡγεῖσθαι plat. estimar menos do que convém, ἐν ἐλάττονι τίθεσθαι pol. ser tido em menor conta 5 submisso a; escravo de, gen.: ἐλάττους τῶν χρημάτων xen. subservientes em relação ao dinheiro ♦ ἔλαττον adv. 6 menos: ἔλ. δέκα ἔτη plat. menos de dez anos, ἔλ. ἔχειν ser inferior em algo, ἐν e dat., em rel. a alguém, παρά e dat., ἔλ. ἢ μηδέν menos que nada, ἔλ. ἄπωθεν menos longínquo ♦ οἱ ἐλάσσονες 7 a minoria.</p></section></article>\n<article id=\"entry-dgp-12955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαστρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1716 na letra ε · nº geral 12955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἠλάστρουν, ép. ἠλάστρεον) 1 pôr em movimento; empurrar; conduzir 2 expulsar; perseguir ♦ pas. 3 ser posto em movimento a remo; navegar.</p></section></article>\n<article id=\"entry-dgp-12956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐλάτεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1717 na letra ε · nº geral 12956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Elatéia, n. de cidade da Fócida e do Épiro.</p></section></article>\n<article id=\"entry-dgp-12957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1718 na letra ε · nº geral 12957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abeto ou madeira de abeto 2 remo 3 navio (feito com madeira de abeto). 〈ἐλάω1〉</p></section></article>\n<article id=\"entry-dgp-12958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλατήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1719 na letra ε · nº geral 12958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 condutor (de animais, de carros) 2 que lança (o trovão, o raio) 3 remador 4 tard. que põe em fuga; que expulsa; que faz dispersar. 〈ἐλάω1〉</p></section></article>\n<article id=\"entry-dgp-12959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλατήριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1720 na letra ε · nº geral 12959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de expulsar; próprio para expulsar, gen. 2 Medic. purgativo ♦ τὸ ἐλατήριον 3 elatério, planta de propriedades purgativas; pepino-do-diabo 4 óleo de sementes de pepino-do-diabo. 〈ἐλατήρ〉</p></section></article>\n<article id=\"entry-dgp-12960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐλατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1721 na letra ε · nº geral 12960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Elatéia. 〈 Ἐλάτεια〉</p></section></article>\n<article id=\"entry-dgp-12961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάτινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1722 na letra ε · nº geral 12961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de abeto 2 feito de madeira de abeto. 〈ἐλάτη〉</p></section></article>\n<article id=\"entry-dgp-12962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαττονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1723 na letra ε · nº geral 12962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ter menos; estar em falta. 〈ἐλάττων〉</p></section></article>\n<article id=\"entry-dgp-12963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαττόω, ἐλάττωμα, ἐλάττων</h1><div class=\"entry-meta\"><span>DGP · ordem 1724 na letra ε · nº geral 12963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át.= ἐλασσόω, ἐλάσσωμα, ἐλάσσων.</p></section></article>\n<article id=\"entry-dgp-12964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάττωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1725 na letra ε · nº geral 12964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. 1 ação de tornar menor; diminuição; perda 2 processo de tornar-se menor; falência; derrota. 〈ἐλασσόω〉</p></section></article>\n<article id=\"entry-dgp-12965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαττωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1726 na letra ε · nº geral 12965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. inclinado a renunciar ao que lhe é devido; ἐλ. ἑαυτοῦ m.aur. que se limita em algo, ἐν e dat. 〈ἐλασσόω〉</p></section></article>\n<article id=\"entry-dgp-12966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαυνέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1727 na letra ε · nº geral 12966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1728 na letra ε · nº geral 12967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἤλαυνον, fut. ἐλάσω, át. ἐλῶ, aor. ἤλασα, aor. iter. ép. ἐλάσασκεν, perf. ἐλήλακα; pas. aor. ἠλάθην, perf. ἐλήλαμαι, m.-q.-perf. ἠληλάμην) ativa 1 impelir adiante; fazer avançar; conduzir 2 lançar diante de si; fincar algo, ac., em, ἐν e dat. 3 impelir; apressar; pressionar à fuga; acossar; perseguir; afligir 4 expulsar; exilar; banir alguém; eliminar algo, de, gen. ou ἐκ e gen. 5 bater em; golpear; ferir 6 alongar; prolongar 7 impelir os cavalos, os navios, o exército; avançar; arremessar-se 8 avançar; vir a um ponto; atingir média 9 levar consigo 1 ἤλασεν ἵππους hom. impeliu os cavalos, ἐλ. τριήρεις plat. fazer avançar trirremes, ἐλ. στρατόν pínd. conduzir o exército, ἥκιστος δ᾽ ἦν αὐτὸς ἐλαυνέμεν ἅρμ᾽ ἐν ἀγῶνι hom. ele era o mais lento a fazer seu carro avançar na corrida 2 σταυροὺς ἐλ. hom. fincar uma fileira de estacas, ἐν σάκει ἤλασεν ἔγχος hom. no seu escudo fincou uma lança, δόρυ δὲ διὰ στήθεσφιν ἔλασσε hom. encravou a lança no peito 3 λῃστὰς ἐλαύνων ar. expulsando piratas, βουβρῶστις ἐπὶ χθόνα ἐλαύνει hom. uma fome terrível afligia a terra, θεὸς ἐλαύνει πόλιν sóf. o deus aflige a cidade 4 ἐκ Τροίης Ἀχαίους ἐλ. hom. expulsar de Tróia os aqueus, τοὺς ἐναγεῖς ἐλ. tuc. expulsar os sacrílegos, μίασμα ἐλ. sóf. eliminar uma mácula 5 τὸν σκήπτρῳ ἐλάσασκεν hom. expulsava-o com golpes de bastão, μιν ἔλασεν σῦς ὁδόντι hom. um javali com suas presas o feriu, ἐλ. κιθαρὰν πλήκτρῳ eur. tocar a cítara com um plectro 6 τάφρον ἐλ. hom. abrir um fosso, ἀμπελίδος ὄρχον ἐλ. artt. plantar uma fileira de vinha 7 ἱμάσθλην χερσὶν ἔχε ᾗπερ ἔλαυνες hom. segura em tua mão o chicote com que impeles os cavalos, οἱ μὲν ὕπνον ᾑροῦντο κατὰ μέρος, οἱ δ᾽ ἤλαυνον hom. uns dormiam, outros, por sua vez, impeliam as naus, εἰς τὰς τάξεις Ἑλλήνων ἐλ. xen. arremessar-se contra as fileiras dos helenos, οἱ πόρρω ἀεὶ τῆς φιλοσοφίας ἐλαύνοντες plat. os que não cessam de avançar na filosofia, ἐλ. ἔξω τοῦ φρονεῖν eur. sair do bom senso 8 ἐλ. ἐς πᾶσαν κακότητα her. chegar a uma maldade completa 9 ῥύσι᾽ ἐλαυνόμενος hom. levando consigo [o gado] como represália, ἠλάσατο τὰς βοῦς plat. conduziu consigo as vacas.</p></section></article>\n<article id=\"entry-dgp-12968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφαβόλος</h1><div class=\"entry-meta\"><span>DGP · ordem 1729 na letra ε · nº geral 12968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἐλαφηβόλος.</p></section></article>\n<article id=\"entry-dgp-12969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάφειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1730 na letra ε · nº geral 12969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cervo ou de corça. 〈ἔλαφος〉</p></section></article>\n<article id=\"entry-dgp-12970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφηβολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1731 na letra ε · nº geral 12970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caça ao cervo. 〈ἐλαφηβόλος〉</p></section></article>\n<article id=\"entry-dgp-12971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφηβόλια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1732 na letra ε · nº geral 12971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Elafebolia, festa de caça aos cervos em honra a Ártemis. 〈ἐλαφηβόλος〉</p></section></article>\n<article id=\"entry-dgp-12972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐλαφηβολιών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1733 na letra ε · nº geral 12972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Elafebólion, 9º mês do calendário ático, correspondente à 2ª quinzena de março e 1ª de abril. 〈ἐλαφηβόλος〉</p></section></article>\n<article id=\"entry-dgp-12973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφηβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1734 na letra ε · nº geral 12973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que atinge ou persegue os cervos. 〈ἔλαφος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-12974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφοκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1735 na letra ε · nº geral 12974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que mata os cervos. 〈ἔλαφος, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-12975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλαφος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1736 na letra ε · nº geral 12975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cervo; corça 2 pele de cervo.</p></section></article>\n<article id=\"entry-dgp-12976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1737 na letra ε · nº geral 12976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. leviandade; frivolidade. 〈ἐλαφρός〉</p></section></article>\n<article id=\"entry-dgp-12977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1738 na letra ε · nº geral 12977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser ágil 2 tornar ágil 3 aliviar. 〈ἐλαφρός〉</p></section></article>\n<article id=\"entry-dgp-12978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1739 na letra ε · nº geral 12978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ágil ao andar; ligeiro: μάλ᾽ ἐλαφρὸς ἀνήρ hom. homem de grande ligeireza, ἐλαφρότατος ποσσί hom. o de pés mais rápidos, ἐλαφρότατος πετεηνῶν hom. o mais ágil dos pássaros, ἐλ. ἡλικία xen. a idade ágil, i.e., a juventude 2 leve; tolerável; fácil de atravessar (rio), de digerir (alimento); moderado (caráter); doce (pessoa): ἐν ἐλαφρῷ ποῖεσθαι her. suportar com facilidade, ἐλαφρόν ἐστι inf. ésql. é coisa fácil, πολεμίζειν οὐκ ἐν ἐλαφρῷ teócr. guerrear não é coisa fácil 3 que dá leveza; que alivia; que suaviza 4 leviano (caráter) 5 de pouco peso; insignificante (cidade).</p></section></article>\n<article id=\"entry-dgp-12979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφρύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1740 na letra ε · nº geral 12979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aliviar; tornar menos pesado; tornar leve. 〈ἐλαφρός〉</p></section></article>\n<article id=\"entry-dgp-12980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλαφρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1741 na letra ε · nº geral 12980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com ligeireza 2 sem fadiga; facilmente.</p></section></article>\n<article id=\"entry-dgp-12981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάχιστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1742 na letra ε · nº geral 12981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(superl. de ἐλαχύς e de ὀλίγος) 1 menor; mínimo; ínfimo 2 o menos numeroso; pouquíssimo ♦ τὸ ἐλάχιστον, τοὐλάχιστον, ἐπ᾽ ἐλάχιστον, ἐλάχιστα adv. 3 pelo menos; ὡς ἐλάχιστα o menos possível, περὶ ἐλαχίστου ποιεῖσθαι plat. considerar o menos possível, δι᾽ ἐλαχίστου tuc. no menor tempo possível, brevíssimo.</p></section></article>\n<article id=\"entry-dgp-12982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλαχον</h1><div class=\"entry-meta\"><span>DGP · ordem 1743 na letra ε · nº geral 12982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de λαγχάνω.</p></section></article>\n<article id=\"entry-dgp-12983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάω1-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1744 na letra ε · nº geral 12983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔλων, fut. ἐλάσω, át. ἐλῶ, aor. e perf. desus.) = ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλάω2</h1><div class=\"entry-meta\"><span>DGP · ordem 1745 na letra ε · nº geral 12984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐλαύνω.</p></section></article>\n<article id=\"entry-dgp-12985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλδομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1746 na letra ε · nº geral 12985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) desejar; almejar; enviar votos de, ac., gen. ou inf.</p></section></article>\n<article id=\"entry-dgp-12986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔλδωρ,</h1><div class=\"entry-meta\"><span>DGP · ordem 1747 na letra ε · nº geral 12986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐέλδωρ só nom. e ac. sing. (τό) anseio; desejo. 〈ἔλδομαι〉</p></section></article>\n<article id=\"entry-dgp-12987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕλε</h1><div class=\"entry-meta\"><span>DGP · ordem 1748 na letra ε · nº geral 12987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imper. aor.2 de αἱρέω.</p></section></article>\n<article id=\"entry-dgp-12988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλεαίρεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 1749 na letra ε · nº geral 12988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de ἐλεαίρω.</p></section></article>\n<article id=\"entry-dgp-12989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλεαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1750 na letra ε · nº geral 12989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. poét. ἐλέαιρον) ter dó; ter piedade de, ac.</p></section></article>\n<article id=\"entry-dgp-12990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐλεάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1751 na letra ε · nº geral 12990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐλεέω.</p></section></article>\n";
